import java.io.PrintStream;
import java.net.URI;
import java.util.concurrent.atomic.AtomicInteger;

import org.springframework.http.HttpMethod;
import org.springframework.web.reactive.function.client.ClientRequest;
import org.springframework.web.reactive.function.client.ExchangeFilterFunction;
import org.springframework.web.util.UriComponentsBuilder;

import reactor.core.publisher.Mono;

public class WebClientFilters {

    private WebClientFilters() {
    }

    public static ExchangeFilterFunction urlModifyingFilter(String version) {
        return ExchangeFilterFunction.ofRequestProcessor(request -> {
            URI oldUrl = request.url();
            URI newUrl = UriComponentsBuilder.fromUri(oldUrl)
                .replacePath(oldUrl.getRawPath() + "/" + version)
                .build(true)
                .toUri();
            return Mono.just(ClientRequest.from(request)
                .url(newUrl)
                .build());
        });
    }

    public static ExchangeFilterFunction countingFilter(AtomicInteger counter) {
        return ExchangeFilterFunction.ofRequestProcessor(request -> {
            if (HttpMethod.GET.equals(request.method())) {
                counter.incrementAndGet();
            }
            return Mono.just(request);
        });
    }

    public static ExchangeFilterFunction loggingFilter(PrintStream printStream) {
        return ExchangeFilterFunction.ofRequestProcessor(request -> {
            printStream.print("Sending request " + request.method() + " " + request.url());
            return Mono.just(request);
        });
    }
}
